  'i18n.fix.0792': 'Ви платите за етапами. Кожен рахунок прив\'язаний до конкретної поставки — коли QA затверджує її, рахунок розблоковується, ви оглядаєте роботу та оплачуєте. Оплата через Stripe (картки) або WayForPay (українські картки). Чеки з\'являються в розділі «Оплата».',
