// Ukrainian noun plural forms keyed by EN singular/plural lowercase.
// Tuple: [singular (1, 21, …), few (2-4, 22-24, …), many (5-20, 0, 25-30, …)].
// Used when the leading token is a plain integer count.
const INLINE_NOUNS_UK_PLURALS: Record<string, [string, string, string]> = {
  'products': ['продукт', 'продукти', 'продуктів'],
  'product': ['продукт', 'продукти', 'продуктів'],
  'modules': ['модуль', 'модулі', 'модулів'],
  'module': ['модуль', 'модулі', 'модулів'],
  'projects': ['проєкт', 'проєкти', 'проєктів'],
  'project': ['проєкт', 'проєкти', 'проєктів'],
  'developers': ['розробник', 'розробники', 'розробників'],
  'developer': ['розробник', 'розробники', 'розробників'],
  'reviews': ['відгук', 'відгуки', 'відгуків'],
  'review': ['відгук', 'відгуки', 'відгуків'],
  'tickets': ['тікет', 'тікети', 'тікетів'],
  'ticket': ['тікет', 'тікети', 'тікетів'],
  'tasks': ['задача', 'задачі', 'задач'],
  'task': ['задача', 'задачі', 'задач'],
  'users': ['користувач', 'користувачі', 'користувачів'],
  'user': ['користувач', 'користувачі', 'користувачів'],
  'messages': ['повідомлення', 'повідомлення', 'повідомлень'],
  'message': ['повідомлення', 'повідомлення', 'повідомлень'],
  'items': ['елемент', 'елементи', 'елементів'],
  'item': ['елемент', 'елементи', 'елементів'],
  'invoices': ['рахунок', 'рахунки', 'рахунків'],
  'invoice': ['рахунок', 'рахунки', 'рахунків'],
  'payments': ['платіж', 'платежі', 'платежів'],
  'payment': ['платіж', 'платежі', 'платежів'],
  'approvals': ['затвердження', 'затвердження', 'затверджень'],
  'approval': ['затвердження', 'затвердження', 'затверджень'],
  'days': ['день', 'дні', 'днів'],
  'day': ['день', 'дні', 'днів'],
  'hours': ['година', 'години', 'годин'],
  'hour': ['година', 'години', 'годин'],
  'minutes': ['хвилина', 'хвилини', 'хвилин'],
  'minute': ['хвилина', 'хвилини', 'хвилин'],
  'seconds': ['секунда', 'секунди', 'секунд'],
  'second': ['секунда', 'секунди', 'секунд'],
  'recent': ['нещодавня', 'нещодавні', 'нещодавніх'],
};

function _ukPluralForm(n: number, forms: [string, string, string]): string {
  const abs = Math.abs(n);
  const mod10 = abs % 10;
  const mod100 = abs % 100;
  if (mod100 >= 11 && mod100 <= 14) return forms[2];
  if (mod10 === 1) return forms[0];
  if (mod10 >= 2 && mod10 <= 4) return forms[1];
  return forms[2];
}

// Smart fallback: tries to translate common dynamic patterns when an exact
// reverse-index lookup misses. Conservative — only handles well-known shapes.
function _smartFallback(en: string, lang: LangCode): string {
  if (lang === 'en') return en;
  const s = en.trim();
  if (!s) return en;

  // Pattern 0: full-string exact via reverse index (already attempted upstream)

  // Pattern 1: leading separator (`·`, `—`, `-`, `/`, `|`) then content.
  // Translate the content part, preserve the separator + spacing.
  const sepMatch = s.match(/^(\s*[·—\-\/|]\s*)(.+)$/);
  if (sepMatch) {
    const inner = _lookupExact(sepMatch[2], lang) ?? _smartFallback(sepMatch[2], lang);
    if (inner !== sepMatch[2]) return sepMatch[1] + inner;
  }

  // Pattern 2: leading number/digits/units + content
  // Examples: "5 reviews", "12 modules", "10/15 done", "$200 on hold",
  //           "$1,200 this month", "3h spent", "5d avg", "12:34 left"
  const numMatch = s.match(/^([\d\s\/\.,\$%\:hHmMdDsS\+\-]+\s+)(.+)$/);
  if (numMatch) {
    const tail = numMatch[2];
    // UA pluralization: if the leading token is a clean integer and the noun
    // has UA plural forms, pick the form by the integer.
    if (lang === 'uk') {
      const intMatch = numMatch[1].trim().match(/^(\d+)$/);
      const forms = INLINE_NOUNS_UK_PLURALS[tail.toLowerCase()];
      if (intMatch && forms) {
        return numMatch[1] + _ukPluralForm(parseInt(intMatch[1], 10), forms);
      }
    }
    // Try exact lookup first
    let translated = _lookupExact(tail, lang);
    if (!translated) {
      const noun = INLINE_NOUNS_UK[tail.toLowerCase()];
      if (noun) translated = noun;
    }
    if (translated) return numMatch[1] + translated;
  }

  // Pattern 2b: leading word(s) followed by numeric tail (e.g. "confidence 92%",
  // "score 4.5"). Translate the leading word, keep the trailing value untouched.
  const wordNumMatch = s.match(/^([A-Za-zА-Яа-яЇїІіЄєҐґ][A-Za-zА-Яа-яЇїІіЄєҐґ\s'\-]*?)(\s+[\d\.,]+%?)$/);
  if (wordNumMatch) {
    const head = wordNumMatch[1];
    const headT = _lookupExact(head, lang);
    if (headT) return headT + wordNumMatch[2];
    const headNoun = INLINE_NOUNS_UK[head.toLowerCase()];
    if (headNoun) return headNoun + wordNumMatch[2];
  }

  // Pattern 3: trailing number/units after content
  // "approval 5", "user 10" — uncommon. Skip.

  // Pattern 4: split by ` · ` / ` — ` separators, translate each segment.
  if (/ [·—] /.test(s)) {
    const parts = s.split(/( [·—] )/);
    let changed = false;
    const out = parts.map((p) => {
      if (/^ [·—] $/.test(p)) return p;
      const t = _lookupExact(p, lang) ?? _smartFallback(p, lang);
      if (t !== p) changed = true;
      return t;
    });
    if (changed) return out.join('');
  }

  // Pattern 5: word lookup for simple noun (no separators / numbers)
  const noun = INLINE_NOUNS_UK[s.toLowerCase()];
  if (noun) return noun;

  return en;
}

export function translateByEn(en: string): string {
  if (typeof en !== 'string') return en;
  const lang = _CURRENT_LANG;
  if (lang === 'en') return en;
  const exact = _lookupExact(en, lang);
  if (exact !== null) return exact;
  return _smartFallback(en, lang);
}

type I18nCtx = {
  lang: LangCode;
  setLang: (next: LangCode, opts?: { syncBackend?: boolean }) => Promise<void>;
  t: (key: string, fallback?: string) => string;
  tByEn: (en: string) => string;
  langs: typeof LANGS;
};

const I18nContext = createContext<I18nCtx>({
  lang: 'en',
  setLang: async () => {},
  t: (k, fb) => fb || k,
  tByEn: (en) => en,
  langs: LANGS,
});

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<LangCode>('en');

  // Hydrate from AsyncStorage on mount.
  useEffect(() => {
    (async () => {
      try {
        const v = await AsyncStorage.getItem(STORAGE_KEY);
        if (v === 'ru') {
          // Russian was removed — migrate any previously-persisted choice to Ukrainian.
          await AsyncStorage.setItem(STORAGE_KEY, 'uk');
          setLangState('uk');
          _setCurrentLang('uk');
        } else if (v === 'en' || v === 'uk') {
          setLangState(v);
          _setCurrentLang(v);
        }
      } catch {/* ignore */}
    })();
  }, []);

  const setLang = useCallback(async (next: LangCode, opts?: { syncBackend?: boolean }) => {
    setLangState(next);
    _setCurrentLang(next);
    try { await AsyncStorage.setItem(STORAGE_KEY, next); } catch {/* ignore */}
    if (opts?.syncBackend !== false) {
      // Best-effort: push preference to backend so it follows the account.
      try { await api.patch('/account/me', { language: next }); } catch {/* unauth or not yet wired — fine */}
    }
  }, []);

  const t = useCallback((key: string, fallback?: string) => {
    const dict = DICTS[lang] || EN;
    return dict[key] ?? EN[key] ?? fallback ?? key;
  }, [lang]);

  // tByEn — mirror of the web `tByEn` pattern. Translate by English literal
  // lookup. Returns the input unchanged if no match (so hardcoded EN strings
  // remain readable on en, and any unknown literal degrades gracefully).
  // Uses smart-fallback patterns (dynamic numbers, separators) for inline
  // template literals like `5 reviews` / `· 12 modules`.
  const tByEn = useCallback((en: string) => {
    if (typeof en !== 'string') return en;
    if (lang === 'en') return en;
    const exact = _lookupExact(en, lang);
    if (exact !== null) return exact;
    return _smartFallback(en, lang);
  }, [lang]);

  const value = useMemo<I18nCtx>(
    () => ({ lang, setLang, t, tByEn, langs: LANGS }),
    [lang, setLang, t, tByEn],
  );

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export function useT() {
  return useContext(I18nContext);
}
